.src { display: block; margin-top: 8px; font-size: .8rem; color: #7a8a7a; }

.panel { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px 22px; margin: 14px 0; }
.panel-src { font-size: .8rem; font-weight: 400; color: var(--muted); }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
@media (max-width: 760px) { .grid2 { grid-template-columns: 1fr; } .hero h1 { font-size: 1.8rem; } }
.fine { font-size: .88rem; color: var(--muted); }
.bullets { padding-left: 20px; }
.bullets li { margin-bottom: 8px; }

.switcher { display: flex; gap: 8px; flex-wrap: wrap; margin: 16px 0 4px; }
.switch-btn { border: 1px solid var(--green); background: #fff; color: var(--green-dark); padding: 8px 14px; border-radius: 999px; font-weight: 700; cursor: pointer; }
.switch-btn:hover { background: #e8f3ea; }
.switch-btn.active { background: var(--green); color: #fff; }
.btn { background: var(--green); color: #fff; border: none; padding: 9px 16px; border-radius: 8px; font-weight: 700; cursor: pointer; }
.btn:hover { background: var(--green-dark); }

.data-table { width: 100%; border-collapse: collapse; font-size: .95rem; }
.data-table th, .data-table td { padding: 8px 10px; border-bottom: 1px solid var(--line); text-align: left; }
.data-table th { background: #eef4ee; }
.data-table .num { text-align: right; font-variant-numeric: tabular-nums; }
.data-table.clickable tbody tr { cursor: pointer; }
.data-table.clickable tbody tr:hover { background: #eef6ee; }
.data-table tbody tr.selected { background: #dcefdd; }
.table-wrap { overflow-x: auto; }

.controls { display: flex; gap: 14px; flex-wrap: wrap; align-items: end; margin: 16px 0 6px; }
.controls label { display: flex; flex-direction: column; font-weight: 700; font-size: .9rem; gap: 4px; }
.controls input, .controls select { padding: 8px 10px; border: 1px solid #b9c6b9; border-radius: 8px; font-size: 1rem; background: #fff; }

.states-layout { display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; align-items: start; }
@media (max-width: 860px) { .states-layout { grid-template-columns: 1fr; } }
.detail { position: sticky; top: 12px; }
.detail.empty { color: var(--muted); }
.facts { margin: 0; }
.facts div { display: flex; justify-content: space-between; gap: 12px; padding: 7px 0; border-bottom: 1px solid var(--line); }
.facts dt { color: var(--muted); }
.facts dd { margin: 0; font-weight: 700; text-align: right; }

.calc { display: flex; gap: 12px; flex-wrap: wrap; align-items: end; margin: 12px 0; }
.calc label { font-weight: 700; display: flex; flex-direction: column; gap: 4px; }
.calc input, .calc select { padding: 8px 10px; border: 1px solid #b9c6b9; border-radius: 8px; font-size: 1rem; }
.calc-result { font-size: 1.2rem; background: #eef6ee; border-radius: 8px; padding: 12px 14px; }
.basket-input { width: 110px; padding: 6px 8px; border: 1px solid #b9c6b9; border-radius: 6px; text-align: right; }

.site-footer { border-top: 1px solid var(--line); padding: 22px 0 30px; color: var(--muted); font-size: .9rem; }
